{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Erythromycin, the closest structural analogue, has an absolute oral bioavailability of 32 ± 7% in healthy subjects, which is above the 20% threshold; roxithromycin is an erythromycin 9-oxime ether designed for improved acid stability and absorption, supporting a high prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Clarithromycin, a semi-synthetic erythromycin derivative with improved acid stability, shows an absolute oral bioavailability of 55% at 250 mg in humans, supporting high bioavailability for similarly stabilized macrolides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Erythromycin estolate, an erythromycin prodrug with enhanced oral absorption, reaches 70-80% absolute oral bioavailability in humans, supporting the high range for erythromycin-derived macrolides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Dirithromycin, a structurally related macrolide, has low oral bioavailability of about 10%, which is contradictory evidence; however, its different 9,11-modification and prodrug-like behavior reduce transferability to roxithromycin.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C15"],
      "claim": "Telithromycin, another semi-synthetic macrolide antibiotic, has an absolute oral bioavailability of 57%, supporting high F for this chemical family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Solithromycin, a modern macrolide, has a mean absolute oral bioavailability of 62% (range 46-80%) in humans, further supporting high oral bioavailability for macrolide derivatives.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is roxithromycin, an erythromycin 9-oxime ether. The most transferable experimental evidence from erythromycin (F ~25-36%), clarithromycin (~55%), erythromycin estolate (70-80%), telithromycin (~57%), and solithromycin (~62-70%) supports F ≥ 20%. The low-F analogues dirithromycin and EM574 are less transferable because of distinct structural modifications or pharmacology. Therefore the prediction is high.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for roxithromycin is present in the supplied evidence.",
    "Dose, formulation, and food effects can influence macrolide bioavailability, but the available analogues consistently exceed the 20% threshold.",
    "The low-F analogues show that macrolide modifications can drastically reduce bioavailability, but their structural differences limit direct transfer to roxithromycin."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

